<template>
  <Dialog
    v-bind="$attrs"
    title="Create New Site"
    size="md"
  >
    <template #body>
      <div class="space-y-4">
        <FormControl label="Site Name">
          <TextInput v-model="form.name" placeholder="site.local" />
        </FormControl>
        <FormControl label="Bench">
          <TextInput v-model="form.bench" placeholder="Select bench..." />
        </FormControl>
      </div>
    </template>
    <template #actions>
      <div class="flex gap-2">
        <Button variant="subtle" @click="$emit('update:modelValue', false)">
          Cancel
        </Button>
        <Button variant="solid" :loading="loading" @click="handleCreate">
          Create
        </Button>
      </div>
    </template>
  </Dialog>
</template>

<script setup>
import { reactive, ref } from "vue"

const emit = defineEmits(["update:modelValue", "created"])
const loading = ref(false)
const form = reactive({
	name: "",
	bench: "",
})

async function handleCreate() {
	loading.value = true
	// In reality, call API here
	setTimeout(() => {
		loading.value = false
		emit("created")
		emit("update:modelValue", false)
	}, 1000)
}
</script>
